      guard let _ = try? from.stat(followTargetSymlink: false) else {
        warn(from.string)
        return true
      }

      let YESNO = "(y/n [n]) "
      ask = 0
      var stderr = FileDescriptor.standardError
      if options.nflg {
        if options.vflg {
          print("\(to) not overwritten")
        }
        return false
      } else if options.iflg {
        print("overwrite \(to)? \(YESNO)", terminator: "", to: &stderr)
        ask = 1
      } else if 0 != Darwin.access(to.string, W_OK),
                let sb = try? to.stat(),
                0 != Darwin.isatty(STDIN_FILENO) {
        let modep = strmode(sb.type, sb.permissions)
        let u = Darwin.user_from_uid(sb.userID.rawValue, 0)!
        let g = Darwin.group_from_gid(sb.groupID.rawValue, 0)!
        print("override \(modep.dropFirst())\(modep.last == " " ? "" : " ")\(u)/\(g) for \(to)? \(YESNO)",
              terminator: "", to: &stderr)
        ask = 1
      }
      if ask != 0 {
        /* Load user specified locale */
        setlocale(LC_MESSAGES, "");

        let chx = readLine()

        /* only care about the first character */
        var resp = chx?.first ?? " "
        if Darwin.rpmatch(&resp) != 1 {
          print("not overwritten", to: &stderr)
          return false
        }
      }
    }
    /*
     * Rename on FreeBSD will fail with EISDIR and ENOTDIR, before failing
     * with EXDEV.  Therefore, copy() doesn't have to perform the checks
     * specified in the Step 3 of the POSIX mv specification.
     */
    if 0 == rename(from.string, to.string) {
      if options.vflg {
        print("\(from.string) -> \(to.string)")
      }
      return false
    }

    if (errno == EXDEV) {
      /*
       * If the source is a symbolic link and is on another
       * filesystem, it can be recreated at the destination.
       */
      guard let sb = try? from.stat(followTargetSymlink: false) else {
        warn(from.string)
        return true
      }
      if sb.type != .symbolicLink {
        /* Can't mv(1) a mount point. */
        guard let pathx = Darwin.realpath(from.string, nil) else {
          warn("cannot resolve \(from)")
          return true
        }
        let path = String(cString: pathx)

        if let sfs = try? FileSystemMetadata(for: path),
           path == sfs.mntonname {
          warnx("cannot rename a mount point")
          return true
        }
      }
    } else {
      warn("rename \(from) to \(to)")
      return true
    }

    /*
     * If rename fails because we're trying to cross devices, and
     * it's a regular file, do the copy internally; otherwise, use
     * cp and rm.
     */
    guard let sb = try? from.stat(followTargetSymlink: false) else {
      warn(from.string);
      return true
    }
    return sb.type == .regular ? fastcopy(from, to, sb) : copy(from, to)
  }

